('Counter-Strike 2', 'Shooter tactico', 'Valve', '2023-09-27', 'M', '5 contra 5', 'Activo', decode('', 'base64')),
('League of Legends', 'MOBA', 'Riot Games', '2009-10-27', 'T', '5 contra 5', 'Activo', decode('', 'base64'));

